static void restart_cb(void *arg)
{
    (void)arg;
    esp_restart();
}

static void restart_soon(void)
{
    static esp_timer_handle_t t;
    if (t == NULL) {
        const esp_timer_create_args_t args = {.callback = restart_cb, .name = "restart"};
        esp_timer_create(&args, &t);
    }
    esp_timer_start_once(t, 1500 * 1000);
}

/*
 * True if the request came in over the setup AP. That network is open to
 * anyone in range, so it only gets the setup page, /save and the favicon.
 */
static bool on_ap(httpd_req_t *req)
{
    return wifi_prov_sock_on_ap(httpd_req_to_sockfd(req));
}

/* Send the captive-portal redirect to the setup page. */
static esp_err_t to_setup_page(httpd_req_t *req)
{
    httpd_resp_set_status(req, "302 Found");
    httpd_resp_set_hdr(req, "Location", AP_HOME);
    return httpd_resp_send(req, NULL, 0);
}

/*
 * CSRF guard for state-changing POSTs: a browser names the page a form came
 * from in Origin (or at least Referer), and it has to be this device as the
 * browser addressed it (the Host header). Requests with neither header (curl,
 * scripts) pass; a page elsewhere cannot make a browser omit both.
 */
static bool same_origin(httpd_req_t *req)
{
    char from[192];
    esp_err_t err = httpd_req_get_hdr_value_str(req, "Origin", from, sizeof(from));
    if (err != ESP_OK && err != ESP_ERR_HTTPD_RESULT_TRUNC) {
        err = httpd_req_get_hdr_value_str(req, "Referer", from, sizeof(from));
        if (err != ESP_OK && err != ESP_ERR_HTTPD_RESULT_TRUNC) {
            return true;
        }
    }
    char host[96];
    if (httpd_req_get_hdr_value_str(req, "Host", host, sizeof(host)) != ESP_OK ||
        !url_origin_matches_host(from, host)) {
        ESP_LOGW(TAG, "refused cross-site POST to %s from %s", req->uri, from);
        return false;
    }
    return true;
}

static esp_err_t cross_site(httpd_req_t *req)
{
    return httpd_resp_send_err(req, HTTPD_403_FORBIDDEN, "cross-site request refused");
}

/* Minimal HTML escaping for SSIDs. */
static void html_escape(const char *in, char *out, size_t out_len)
{
    size_t o = 0;
    for (; *in && o + 7 < out_len; in++) {
        const char *rep = NULL;
        switch (*in) {
        case '&': rep = "&amp;"; break;
        case '<': rep = "&lt;"; break;
        case '>': rep = "&gt;"; break;
        case '"': rep = "&quot;"; break;
        case '\'': rep = "&#39;"; break;
        default: break;
        }
        if (rep) {
            size_t l = strlen(rep);
            memcpy(out + o, rep, l);
            o += l;
        } else {
            out[o++] = *in;
        }
    }
    out[o] = '\0';
}

static esp_err_t send_setup_page(httpd_req_t *req)
{
    httpd_resp_set_type(req, "text/html");
    httpd_resp_sendstr_chunk(req, PAGE_HEAD);
    httpd_resp_sendstr_chunk(req, "<h2>" LOGO_SVG "ZebSerial WiFi setup</h2><form method=post action=/save>"
                                  "<label>Network</label><select name=ssid>");
    /*
     * Phones fire several captive-portal probes that all land here; scanning
     * on each one disrupts the AP, so reuse a recent scan unless asked.
     */
    static wifi_ap_record_t recs[MAX_SCAN];
    static int n;
    static int64_t scanned_at;
    char q[16] = "";
    bool want_rescan = httpd_req_get_url_query_str(req, q, sizeof(q)) == ESP_OK && strstr(q, "rescan") != NULL;
    int64_t now = esp_timer_get_time();
    if (want_rescan || scanned_at == 0 || now - scanned_at > SCAN_MAX_AGE_US) {
        n = wifi_prov_scan(recs, MAX_SCAN);
        scanned_at = now;
    }
    char esc[200];
    char line[512];
    for (int i = 0; i < n; i++) {
        const char *ssid = (const char *)recs[i].ssid;
        if (ssid[0] == '\0') {
            continue;
        }
        bool dup = false;
        for (int j = 0; j < i; j++) {
            dup |= strcmp(ssid, (const char *)recs[j].ssid) == 0;
        }
        if (dup) {
            continue;
        }
        html_escape(ssid, esc, sizeof(esc));
        snprintf(line, sizeof(line), "<option value=\"%s\">%s (%d dBm)</option>", esc, esc, recs[i].rssi);
        httpd_resp_sendstr_chunk(req, line);
    }
    httpd_resp_sendstr_chunk(req, "</select>"
                                  "<label>or type a network name</label><input name=ssid_manual maxlength=32>"
                                  "<label>Password</label><input name=pass type=password maxlength=64>"
                                  "<button type=submit>Save and reboot</button></form>"
                                  "<p><a href='/?rescan=1'>Scan again</a></p>");
    httpd_resp_sendstr_chunk(req, PAGE_TAIL);
    return httpd_resp_sendstr_chunk(req, NULL);
}

